import { useState, useEffect } from 'react';
import API from '../services/api';

export default function Reports() {
  const [uploadSummary, setUploadSummary] = useState([]);
  const [userActivity, setUserActivity] = useState([]);
  const [deptReport, setDeptReport] = useState([]);
  const [activeTab, setActiveTab] = useState('upload');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchAll = async () => {
      setLoading(true);
      try {
        const [u, a, d] = await Promise.all([
          API.get('/reports/upload-summary'),
          API.get('/reports/user-activity'),
          API.get('/reports/department')
        ]);
        setUploadSummary(u.data);
        setUserActivity(a.data);
        setDeptReport(d.data);
      } catch {}
      setLoading(false);
    };
    fetchAll();
  }, []);

  const tabs = [
    { key: 'upload', label: 'Upload Summary' },
    { key: 'activity', label: 'User Activity' },
    { key: 'department', label: 'Department Report' }
  ];

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Reports</h2>
      <div style={styles.tabs}>
        {tabs.map(t => (
          <button key={t.key} style={{ ...styles.tab, ...(activeTab === t.key ? styles.activeTab : {}) }}
            onClick={() => setActiveTab(t.key)}>{t.label}</button>
        ))}
      </div>

      {loading ? <p>Loading...</p> : (
        <div style={styles.content}>
          {activeTab === 'upload' && (
            <>
              <h3>Document Upload Summary (Last 30 Days)</h3>
              <table style={styles.table}>
                <thead><tr style={styles.thead}>
                  <th style={styles.th}>Date</th>
                  <th style={styles.th}>Documents Uploaded</th>
                  <th style={styles.th}>Total Size (KB)</th>
                </tr></thead>
                <tbody>
                  {uploadSummary.map(r => (
                    <tr key={r._id} style={styles.tr}>
                      <td style={styles.td}>{r._id}</td>
                      <td style={styles.td}>{r.count}</td>
                      <td style={styles.td}>{(r.totalSize / 1024).toFixed(1)}</td>
                    </tr>
                  ))}
                  {uploadSummary.length === 0 && <tr><td colSpan="3" style={{ ...styles.td, textAlign: 'center', color: '#999' }}>No data</td></tr>}
                </tbody>
              </table>
            </>
          )}

          {activeTab === 'activity' && (
            <>
              <h3>User Activity Report</h3>
              <table style={styles.table}>
                <thead><tr style={styles.thead}>
                  <th style={styles.th}>User</th>
                  <th style={styles.th}>Total Actions</th>
                  <th style={styles.th}>Action Breakdown</th>
                </tr></thead>
                <tbody>
                  {userActivity.map(r => (
                    <tr key={r._id} style={styles.tr}>
                      <td style={styles.td}>{r._id}</td>
                      <td style={styles.td}>{r.total}</td>
                      <td style={styles.td}>{r.actions.map(a => `${a.action}: ${a.count}`).join(' | ')}</td>
                    </tr>
                  ))}
                  {userActivity.length === 0 && <tr><td colSpan="3" style={{ ...styles.td, textAlign: 'center', color: '#999' }}>No data</td></tr>}
                </tbody>
              </table>
            </>
          )}

          {activeTab === 'department' && (
            <>
              <h3>Department-wise Document Report</h3>
              <table style={styles.table}>
                <thead><tr style={styles.thead}>
                  <th style={styles.th}>Department</th>
                  <th style={styles.th}>Documents</th>
                  <th style={styles.th}>Total Size (KB)</th>
                </tr></thead>
                <tbody>
                  {deptReport.map(r => (
                    <tr key={r._id} style={styles.tr}>
                      <td style={styles.td}>{r._id}</td>
                      <td style={styles.td}>{r.count}</td>
                      <td style={styles.td}>{(r.totalSize / 1024).toFixed(1)}</td>
                    </tr>
                  ))}
                  {deptReport.length === 0 && <tr><td colSpan="3" style={{ ...styles.td, textAlign: 'center', color: '#999' }}>No data</td></tr>}
                </tbody>
              </table>
            </>
          )}
        </div>
      )}
    </div>
  );
}

const styles = {
  container: { padding: '24px', maxWidth: '1000px', margin: '0 auto' },
  heading: { color: '#1a237e', marginBottom: '16px' },
  tabs: { display: 'flex', gap: '8px', marginBottom: '20px' },
  tab: { padding: '8px 18px', border: '1px solid #ccc', borderRadius: '4px', cursor: 'pointer', background: '#fff', fontSize: '14px' },
  activeTab: { background: '#1a237e', color: '#fff', border: '1px solid #1a237e' },
  content: { background: '#fff', padding: '20px', borderRadius: '8px', boxShadow: '0 1px 6px rgba(0,0,0,0.1)' },
  table: { width: '100%', borderCollapse: 'collapse', marginTop: '12px' },
  thead: { background: '#e8eaf6' },
  th: { padding: '10px 12px', textAlign: 'left', fontSize: '13px', fontWeight: '600' },
  tr: { borderBottom: '1px solid #eee' },
  td: { padding: '10px 12px', fontSize: '13px' }
};
